import { useState } from "react";
import { SelectField } from "@/shared/ui/controls/Field";
import { Card } from "@/shared/ui/data/Card";

// Vendored from `@/app/console/lib/models` (unresolvable — the real MODELS catalog loads from
// `@data/console/models.json`); representative sample data matching the real ModelId union.
const MODELS = [
  { id: "haiku-4.5", tone: "fast", price: "$" },
  { id: "sonnet-4.5", tone: "balanced", price: "$$" },
  { id: "opus-4.5", tone: "deep", price: "$$$" },
];

// Preview-only stand-in for `useAppStore().defaultModel` / `setDefaultModel` (app-internal).
export function DefaultModelCard() {
  const [defaultModel, setDefaultModel] = useState("sonnet-4.5");

  return (
    <Card title="Default model">
      <SelectField
        label="Model new consoles open with"
        value={defaultModel}
        onChange={(v) => setDefaultModel(v)}
        hint="Per-pane override is available from the pane hamburger menu."
      >
        {MODELS.map((m) => (
          <option key={m.id} value={m.id}>{m.id} · {m.tone}</option>
        ))}
      </SelectField>
    </Card>
  );
}
